// Write your Character and Word Counter logic here
const textInput = document.getElementById('textInput');
const charCount = document.getElementById('charCount');
const wordCount = document.getElementById('wordCount');
const progressBar = document.getElementById('progressBar');
const MAX_CHARS = 200;

textInput?.addEventListener('input', () => {
  const text = textInput.value;
  const chars = text.length;

  // Count words
  const trimmed = text.trim();
  const words = trimmed ? trimmed.split(/\s+/).length : 0;

  // Calculate percent
  const percent = Math.min(100, (chars / MAX_CHARS) * 100);
  const isNearLimit = MAX_CHARS - chars <= 15;

  charCount.textContent = `${chars} / ${MAX_CHARS}`;
  wordCount.textContent = words;
  progressBar.style.width = `${percent}%`;

  progressBar.classList.toggle('warning', isNearLimit);
  charCount.classList.toggle('warning', isNearLimit);
});
